// The GotMyGame wordmark for PDFs: the same transparent artwork the app uses (apps/api/assets/brand, generated by scripts/brand/render.mjs).
import { fileURLToPath } from 'node:url';

const file = (f) => fileURLToPath(new URL(`../../assets/brand/${f}`, import.meta.url));
export const WORDMARK = { name: file('wordmark.png'), nameRatio: 1651 / 339, tagline: file('wordmark-tagline.png'), taglineRatio: 1676 / 518 };

/**
 * Draws "GotMyGame" with its top-left at (x, y) and leaves doc.y just below it. `size` is roughly the letter height in points
 * (the artwork is about 4.9 times as wide); `tagline` uses the lockup with the swoosh and "THE SPORTSVERSE" (for white paper).
 * Returns the width used.
 */
export function drawWordmark(doc, x, y, { size = 14, tagline = false } = {}) {
  const width = size * 4.9, ratio = tagline ? WORDMARK.taglineRatio : WORDMARK.nameRatio, height = width / ratio;
  doc.image(tagline ? WORDMARK.tagline : WORDMARK.name, x, y, { width });
  doc.x = x; doc.y = y + height + 2;
  return width;
}
